changeSet.sql:
ALTER TABLE payment
ADD CONSTRAINT chk_payment_amount CHECK (amount > 0),
ADD CONSTRAINT chk_payment_commission_amount CHECK (commission_amount >= 0),
ADD CONSTRAINT chk_payment_total_amount CHECK (total_amount > 0);

ALTER TABLE agent
ADD CONSTRAINT chk_agent_balance CHECK (balance >= 0);
ALTER TABLE payment
ADD CONSTRAINT chk_payment_agent_id CHECK (agent_id IS NOT NULL);

ALTER TABLE top_up_ledger
ADD CONSTRAINT chk_top_up_ledger_amount CHECK (amount > 0),
ADD CONSTRAINT chk_top_up_ledger_balance_before CHECK (balance_before >= 0),
ADD CONSTRAINT chk_top_up_ledger_balance_after CHECK (balance_after >= 0);
